SELECT eaf.attachment_id, eaf.message_id AS draft_id, ea.provider_attachment_id, orig_msg.provider_id AS "message_provider_id!", ea.filename, ea.mime_type, ea.size_bytes FROM email_attachments_fwd eaf JOIN email_attachments ea ON eaf.attachment_id = ea.id JOIN email_messages orig_msg ON ea.message_id = orig_msg.id WHERE eaf.message_id = ANY($1) ORDER BY eaf.message_id, ea.filename ASC
